// Renders `.env.example` from the schema registry. Pure and deterministic: no clock, no env reads.
import type { KeySpec } from './registry.ts';
import { envRegistry } from './schema.ts';

const HEADER = [
  '# CauseDeck environment variables.',
  '# Generated by `pnpm env:example` from packages/config/src/env. Do not edit by hand.',
  '# Every integration defaults to a mock or console provider, so dev and CI need no secrets.',
  '# Reference: docs/engineering/env.md',
];

function renderKey(spec: KeySpec): string[] {
  const notes = [
    `type: ${spec.type}`,
    `required when: ${spec.requiredWhen}`,
    `owner: #${String(spec.ownerIssue)}`,
  ];
  if (spec.credentialIssue !== undefined)
    notes.push(`credential: #${String(spec.credentialIssue)}`);
  if (spec.devDefault !== undefined && !spec.secret)
    notes.push(`local default: ${spec.devDefault}`);
  if (spec.devDefault !== undefined && spec.secret) notes.push('local default: dev placeholder');
  const lines = [`# ${spec.description}`, `# ${notes.join('; ')}`];
  if (spec.name.includes('*')) {
    lines.push(`# ${spec.name.replace('*', '<NAME>')}=false`);
  } else {
    // Only environment-independent defaults are written out; dev defaults stay implicit so a copied
    // file never pins local values in production.
    lines.push(`${spec.name}=${spec.secret ? '' : (spec.default ?? '')}`);
  }
  return lines;
}

export function renderEnvExample(registry: readonly KeySpec[] = envRegistry): string {
  const out = [...HEADER];
  let domain: string | undefined;
  for (const spec of registry) {
    if (spec.domain !== domain) {
      domain = spec.domain;
      out.push('', `# ---- ${domain} ----`);
    }
    out.push('', ...renderKey(spec));
  }
  return `${out.join('\n')}\n`;
}
